examples.template:
MonarchButton(text = {{link}}, onClick = { open = true })
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }) {
        MonarchConsentPreferences(
            categories = categories,
            onDecide = { method, decided ->
                choices = decided
                // Store a MonarchConsentRecord with the method and the policy version here.
                open = false
            },
            modifier = Modifier.verticalScroll(rememberScrollState()),
            choices = choices,
            onPolicyClick = { /* open the policy */ },
            labels = MonarchConsentPreferencesLabels(
                title = "Cookie settings",
                description = "Choose which optional cookies we may use. Strictly necessary cookies keep the site working and are always on.",
                policy = "Cookie policy",
            ),
        )
    }
}

examples.setupTemplate:
var open by remember { mutableStateOf(true) }
var choices by rememberSaveable { mutableStateOf(mapOf<String, Boolean>()) }
val categories = listOf(
    MonarchConsentPreferencesCategory({{categories.0.id}}, {{categories.0.label}}, {{categories.0.description}}, required = true),
    MonarchConsentPreferencesCategory({{categories.1.id}}, {{categories.1.label}}, {{categories.1.description}}),
    MonarchConsentPreferencesCategory({{categories.2.id}}, {{categories.2.label}}, {{categories.2.description}}),
    MonarchConsentPreferencesCategory({{categories.3.id}}, {{categories.3.label}}, {{categories.3.description}}, saleOrSharing = true),
)

examples.setup:
var open by remember { mutableStateOf(true) }
var choices by rememberSaveable { mutableStateOf(mapOf<String, Boolean>()) }
val categories = listOf(
    MonarchConsentPreferencesCategory("necessary", "Strictly necessary", "Keeps you signed in, remembers your security settings and makes the site work.", required = true),
    MonarchConsentPreferencesCategory("preferences", "Preferences", "Remembers choices such as language and theme."),
    MonarchConsentPreferencesCategory("analytics", "Analytics", "Counts visits and measures how features are used, so we can improve them."),
    MonarchConsentPreferencesCategory("marketing", "Marketing", "Measures campaigns and shows relevant ads on other sites.", saleOrSharing = true),
)

